-- One row per successful reading and one column per register, per device, instead of one row per value:
-- ~16x smaller (rehearsed 2026-10-11: 28 MB instead of 461 MB) and simpler SQL. Generated from the register map of
-- 2026-10-11 by scratch/gen_migration_0004.py; frozen like every applied migration.
--
--   raw_plant_register_values, raw_inverter_register_values   tables: reading_id, started_at (copied from
--       readings), then each register as its decoded integer BEFORE the gain (u64: the same-bits signed number,
--       so "not set" is -1), NULL if a register wasn't in the map yet when the reading was taken
--   plant_register_values, inverter_register_values           views: the same, scaled (value / gain), each column
--       named <register>_<unit> (kw, kwh, kvar, kva, v, a, pct, c, s, hz, min, megohm; none without a unit)
--   register_values                                           view: the old (reading_id, address, value) shape,
--       rebuilt from the raw tables, so existing queries keep working (slower than the raw tables)
--   register_values_v1                                        the old table, renamed and kept until a later
--       migration drops it
--
-- The copy is incremental (see migrations/backfill/0004_wide_values.sql, the same step on its own): readings
-- already copied by a backfill run are skipped, so with a recent backfill this only copies the last few minutes.
-- Everything copied is checked value for value; any difference aborts the migration (one transaction).

CREATE TABLE IF NOT EXISTS raw_plant_register_values (
    reading_id                                     BIGINT      PRIMARY KEY REFERENCES readings (id) ON DELETE CASCADE,
    started_at                                     TIMESTAMPTZ NOT NULL,
