-- This run's batch: the successful readings not copied yet. Values are written in the same transaction as their
-- reading, so a committed reading has all of them.
CREATE TEMP TABLE wide_batch ON COMMIT DROP AS
SELECT r.id, r.started_at FROM readings r
WHERE r.error IS NULL
  AND NOT EXISTS (SELECT 1 FROM raw_plant_register_values p WHERE p.reading_id = r.id)
  AND NOT EXISTS (SELECT 1 FROM raw_inverter_register_values i WHERE i.reading_id = r.id);
ANALYZE wide_batch;

