-- Every value is now in the wide tables: earlier backfill runs checked theirs, this run checked the rest.
DO $$
DECLARE
    before BIGINT;
    after  BIGINT;
BEGIN
    SELECT count(*) INTO before FROM register_values_v1;
    SELECT count(*) INTO after FROM register_values;
    IF before <> after THEN
        RAISE EXCEPTION '0004: % values in register_values_v1, % in the wide tables', before, after;
    END IF;
END $$;
